return (async () => {
// The two examples the reference shows open (previews 4 and 5, "Sides" and "Skip transition"): every
// card pinned open, the pointer ignored so a stray hover cannot close one mid-read.
//
// Placement flips to whichever side has room, measured against the viewport AT THE MOMENT a card
// opens. That is correct behaviour, and it makes the open a measurement in its own right: whatever the
// page looks like when `shown` lands is what the card resolves against. Two consequences, both of
// which reported differences that were the harness's fault rather than the element's:
//
//   - The census sets each preview's `width` AFTER prepare runs, so a card opened here sees the docs
//     page's natural 958px column. That pushes the fourth trigger to x≈1119 in a 1333-wide viewport,
//     leaving 177px where the card needs 311, so `right` correctly flips to `left` — while the
//     reference, whose trigger sits at x≈869 with 459px of room, opens right. Set the width first.
//   - A group still below the fold measures its trigger at y≈1100 in a 924-tall window, so every card
//     flips to `top` whatever it asked for. Our docs page is taller than the mirror, so the same
//     example sits lower; scroll each group to the reference's own trigger offset before opening.
const REFERENCE_TRIGGER_Y = 637;
const PREVIEW_WIDTH = "600px";
const previews = [...document.querySelectorAll(".showcase .preview")];
const settle = () => new Promise((r) => setTimeout(r, 150));
for (const preview of previews) preview.style.width = PREVIEW_WIDTH;
await settle();
for (const preview of previews.slice(3)) {
  const els = [...preview.querySelectorAll("acme-context-card")];
  if (!els.length) continue;
  const top = els[0].getBoundingClientRect().top + window.scrollY;
  window.scrollTo({ top: Math.max(0, top - REFERENCE_TRIGGER_Y), behavior: "instant" });
  await settle();
  for (const el of els) { el.disableTriggers = true; el.shown = 1; }
  await Promise.all(els.map((el) => el.updateComplete));
  await settle();
}
})();
